result:
**The bug:** `decoded.exp < Date.now() / 1000` uses strict less-than, so a token where `exp === now` passes the check and is accepted — violating RFC 7519, which says tokens MUST NOT be accepted *on or after* the expiry time.

**Deeper issue:** The manual `exp` check is also redundant. `jwt.verify()` already validates expiry correctly (using `>=`). The manual check only runs on already-verified tokens, meaning it can never catch anything `jwt.verify` didn't already catch — except it has the off-by-one bug, making it a net negative.

**Fix:** Remove the broken manual check and instead distinguish error types in the catch block, which is what was missing for proper error handling.

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Covers NotBeforeError and unexpected failures (e.g. missing JWT_SECRET)
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Before | After |
|---|---|---|
| Boundary bug | `exp < now` accepts tokens at exact expiry | Removed — `jwt.verify` uses `exp >= now` correctly |
| Expired vs. invalid | Both returned same 401 message | `TokenExpiredError` vs `JsonWebTokenError` distinguished |
| Unexpected errors (missing secret, etc.) | Generic 401 | 500 to avoid leaking auth detail |
